// gsap-button-feedback.js
import { gsap } from "gsap";
import { Physics2DPlugin } from "gsap/Physics2DPlugin";
import { CustomBounce } from "gsap/CustomBounce";
import { CustomEase } from "gsap/CustomEase";

gsap.registerPlugin(Physics2DPlugin, CustomBounce, CustomEase);

// Register a tactile bounce once at module scope
CustomBounce.create("btnBounce", { strength: 0.55, endAtStart: false, squash: 1.4 });

/**
 * Tactile click feedback for a single button.
 * @param {HTMLElement} el      - the button
 * @param {string}      flash   - CSS color for the per-button flash (e.g. var(--like))
 * @param {boolean}     burst   - true for Like (spawn confetti particles)
 */
export function pressFeedback(el, flash, burst = false) {
  const tl = gsap.timeline({ defaults: { overwrite: "auto" } });

  // 1. Physics-y squish & rebound on transform (CustomBounce)
  tl.fromTo(el,
    { scale: 0.86, y: 2 },
    { scale: 1, y: 0, duration: 0.9, ease: "btnBounce" },
    0
  );
  // squashY runs slightly behind so the button "lands" then settles
  tl.fromTo(el,
    { scaleY: 0.78, scaleX: 1.12 },
    { scaleY: 1, scaleX: 1, duration: 0.9, ease: "btnBounce-squash" },
    0
  );

  // 2. Per-button color flash via CSS variable on the element itself
  // Each button sets its own --flash-color in CSS; here we override inline
  // and tween it back to transparent so the ring/glow fades on the SAME timeline.
  el.style.setProperty("--flash-color", flash);
  tl.fromTo(el,
    { "--flash-alpha": 0.85 },
    { "--flash-alpha": 0, duration: 0.55, ease: CustomEase.create("flashOut", "M0,0 C0.2,1 0.3,1 1,1") },
    0.02
  );

  // 3. Optional Physics2D confetti burst (Like only)
  if (burst) {
    const rect = el.getBoundingClientRect();
    const host = el.ownerDocument.body;
    for (let i = 0; i < 14; i++) {
      const p = host.appendChild(document.createElement("span"));
      p.className = "fx-particle";
      p.style.cssText = `
        position:fixed;left:${rect.left + rect.width / 2}px;top:${rect.top + rect.height / 2}px;
        width:6px;height:6px;border-radius:999px;background:${flash};pointer-events:none;z-index:9999;`;
      tl.to(p, {
        physics2D: {
          velocity: gsap.utils.random(260, 420),
          angle:    gsap.utils.random(-110, -70),  // upward fan
          gravity:  900,
          friction: 0.06,
        },
        opacity: 0,
        scale: 0.4,
        duration: 0.9,
        ease: "power1.out",
        onComplete: () => p.remove(),
      }, 0);
    }
  }
  return tl;
}

