// ReadingViewActions.tsx
import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import { gsap } from "gsap";
import { Physics2DPlugin } from "gsap/Physics2DPlugin";
import { CustomBounce } from "gsap/CustomBounce";
import { CustomEase } from "gsap/CustomEase";
import { pressFeedback } from "./gsap-button-feedback";

gsap.registerPlugin(useGSAP, Physics2DPlugin, CustomBounce, CustomEase);

export function ReadingViewActions({ onLike, onSave, onShare }) {
  const scope = useRef<HTMLDivElement>(null);

  // Register the named bounce exactly once inside scope
  useGSAP(() => {
    CustomBounce.create("btnBounce", { strength: 0.55, squash: 1.4, endAtStart: false });
  }, { scope });

  const { contextSafe } = useGSAP({ scope });

  const handleLike  = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--like)",  true ); onLike(); });
  const handleSave  = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--gold)",  false); onSave(); });
  const handleShare = contextSafe!((e) => { pressFeedback(e.currentTarget, "var(--ink-2)", false); onShare(); });

  return (
    <div ref={scope} className="reading-actions">
      <button className="rv-btn rv-like"  style={{ ["--flash-color" as any]: "var(--like)" }}  onClick={handleLike}>Like</button>
      <button className="rv-btn rv-save"  style={{ ["--flash-color" as any]: "var(--gold)" }}  onClick={handleSave}>Save</button>
      <button className="rv-btn rv-share" style={{ ["--flash-color" as any]: "var(--ink-2)" }} onClick={handleShare}>Share</button>
    </div>
  );
}

/* CSS — each button reads --flash-color + --flash-alpha; the tween drives alpha back to 0
.rv-btn {
  --flash-alpha: 0;
  position: relative; isolation: isolate;
  transform-origin: 50% 60%;             // bias rebound toward thumb contact
  will-change: transform;
}
.rv-btn::after {
  content: ""; position: absolute; inset: -2px; border-radius: inherit;
  background: var(--flash-color); opacity: var(--flash-alpha);
  filter: blur(6px); z-index: -1; pointer-events: none;
  transition: none;                       // GSAP owns this var
}
.rv-like  { --like: #ff3860; }
.rv-save  { --gold: #d4a24a; }
.rv-share { --ink-2: rgba(255,255,255,0.55); }
*/
